def count_good_subarrays(s):
    # s is the string of digits
    n = len(s)

    # Calculate prefix sums of (digit - 1)
    prefix = [0] * (n + 1)
    for i in range(n):
        prefix[i+1] = prefix[i] + int(s[i]) - 1

    # Count occurrences of each prefix sum
    count = {}
    for i in range(n + 1):
        count[prefix[i]] = count.get(prefix[i], 0) + 1

    # Calculate total good subarrays
    total = 0
    for c in count.values():
        if c >= 2:
            total += c * (c - 1) // 2
    return total

t = int(input())
for _ in range(t):
    n = int(input())
    s = input().strip()
    print(count_good_subarrays(s))
"}

