def count_operations(s):

    # Parse the input string into a list of colors
    colors = list(s)

    # Get the length of the string
    n = len(colors)

    # If there's only one point, no operations can be done
    if n == 1:
        return 0

    # Initialize layers
    layers = []

    # First pass: find all points that will be deleted in the first operation
    layer_0 = []
    for i in range(n):
        # Check if left neighbor is different color
        if i > 0 and colors[i] != colors[i-1]:
            layer_0.append(i)
        # Check if right neighbor is different color
        if i < n - 1 and colors[i] != colors[i+1]:
            layer_0.append(i)

    # Remove duplicates from layer_0
    layer_0 = list(set(layer_0))

    if not layer_0:
        # No deletions in first operation, so we're done
        return 0

    # Remove the points that will be deleted in the first operation
    for idx in sorted(layer_0, reverse=True):
        colors.pop(idx)

    layers.append(layer_0)

    # Continue with remaining points
    while True:
        # Find next layer
        next_layer = []
        for i in range(len(colors)):
            # Check if left neighbor is different color
            if i > 0 and colors[i] != colors[i-1]:
                next_layer.append(i)
            # Check if right neighbor is different color
            if i < len(colors) - 1 and colors[i] != colors[i+1]:
                next_layer.append(i)

        if not next_layer:
            break

        # Remove duplicates
        next_layer = list(set(next_layer))

        # Remove the points from this layer
        for idx in sorted(next_layer, reverse=True):
            colors.pop(idx)

        layers.append(next_layer)

    return len(layers)

if __name__ == "__main__":
    s = input().strip()
    print(count_operations(s))
"}

