# Problem: 514_A - Chewbacca and Number
# We need to find the minimum possible number by inverting digits
# Inverting digit t means replacing it with 9 - t

x = input().strip()

# Convert to a list of characters for easier manipulation
digits = list(x)

# Apply the transformation rules to each digit
for i in range(len(digits)):
    if i == 0:
        # First digit - can't be 0
        if digits[i] == '0':
            # Leading zero - invert to 9
            digits[i] = '9'
        elif digits[i] == '9':
            # First digit of 9 - keep as is
            digits[i] = '9'
        else:
            d = int(digits[i])
            if 5 <= d <= 8:
                # Invert to get smaller
                digits[i] = str(9 - d)
            elif d == 1:
                # Keep as 1
                pass

    else:
        # Non-first digit - can be 0
        d = int(digits[i])
        if 2 <= d <= 4:
            # Keep as is
            pass
        elif 5 <= d <= 8:
            # Invert to get smaller
            digits[i] = str(9 - d)
        elif d == 9:
            # Invert to 0
            digits[i] = '0'

result = ''.join(digits)

print(result)
"}

