def construct_k_regular_graph(k):
    # For k odd, we can use the bridge construction
    if k % 2 == 1:
        # Create a central vertex with degree k
        # Connect it to k other vertices
        # Connect the k vertices in a cycle

        vertices = []
        for i in range(k + 1):
            vertices.append(i + 1)

        edges = []
        # Connect central vertex to all others
        for i in range(1, k + 1):
            edges.append((vertices[0], vertices[i]))

        # Connect the other vertices in a cycle
        for i in range(1, k + 1):
            edges.append((vertices[i], vertices[(i+1) % k]))

        return edges
    else:
        # For k even, we need a different approach
        # Let's create two complete graphs
        # Connect them with a bridge

        num_vertices_per_part = k + 1
        vertices = []
        for i in range(2 * num_vertices_per_part):
            vertices.append(i + 1)

        edges = []
        # Complete graph 1
        for i in range(num_vertices_per_part):
            for j in range(i+1, num_vertices_per_part):
                edges.append((vertices[i], vertices[j]))

        # Complete graph 2
        for i in range(num_vertices_per_part, 2 * num_vertices_per_part):
            for j in range(i+1, 2 * num_vertices_per_part):
                edges.append((vertices[i], vertices[j]))

        # Add the bridge
        edges.append((vertices[0], vertices[num_vertices_per_part]))

        return edges

k = int(input())

if k == 1:
    print("YES")
    print("2 1")
    print("1 2")
elif k % 2 == 1:
    print("YES")
    edges = construct_k_regular_graph(k)
    print(len(edges) * 2, len(edges))
    for a, b in edges:
        print(a, b)
else:
    print("NO")
"}

