# Calculate z from first experiment
if k == 1:
    z = t + b * n
else:
    z = k**n * t + b * (k**n - 1) // (k - 1)

# Calculate m for second experiment
if k == 1:
    # f(n) = t + b*n, so f(m) = t + b*m
    m = max(0, (z - t + b - 1) // b)  # Use ceiling division
else:
    # f(n) = k^n * t + b * (k^n - 1) / (k - 1)
    # We want k^m * t + b * (k^m - 1) / (k - 1) >= z
    # Solve for m
