for _ in range(t):
    n, m = map(int, input().split())
    a = list(map(int, input().split()))

    # Greedy approach to partition into m-divisible arrays
    # Let's try a different greedy: place elements in the current array if they can be adjacent to any element
    # But if no element in the array can form a valid adjacent pair, start new array

    current_array = []
    result = 0

    for num in a:
        if len(current_array) == 0:
            current_array.append(num)
            result += 1
        else:
            # Check if num can be adjacent to any element in the current array
            valid = False
            for elem in current_array:
                if (elem + num) % m == 0:
                    valid = True
                    break
            if valid:
                # Place with the first element that works (this is arbitrary but keeps things simple)
                for i, elem in enumerate(current_array):
                    if (elem + num) % m == 0:
                        current_array.insert(i, num)
                        break
            else:
                # Start new array
                current_array = [num]
                result += 1

    print(result)
