def solve():
    import sys
    input = sys.stdin.read
    data = input().split()
    if not data:
        return
    it = iter(data)
    T = int(next(it))
    out_lines = []
    for _ in range(T):
        n = int(next(it))
        a = [int(next(it)) for _ in range(n)]
        if n < 2:
            out_lines.append("-1")
            continue
        # Sliding window
        from collections import defaultdict
        freq = defaultdict(int)
        freq_of_count = defaultdict(int)
        max_freq = 0
        left = 0
        answer = float('inf')
        for right in range(n):
            v = a[right]
            freq[v] += 1
            # Update freq_of_count and max_freq
            old_count = freq[v] - 1
            freq_of_count[old_count] -= 1
            if freq_of_count[old_count] == 0:
                del freq_of_count[old_count]
            freq_of_count[freq[v]] += 1
            if freq_of_count[freq[v]] == 1:
                if freq[v] > max_freq:
                    max_freq = freq[v]
            # Now check if max_freq > half window
            window_len = right - left + 1
            if max_freq > window_len / 2:
                # Might be able to shrink left
                while max_freq > (window_len - 1) / 2 and left <= right:
                    # Before shrink, check if we have a valid subarray
                    if max_freq > window_len / 2:
                        answer = min(answer, window_len)
                    # Shrink left
                    u = a[left]
                    freq[u] -= 1
                    if freq[u] == 0:
                        del freq[u]
                    old_count = freq[u] + 1
                    freq_of_count[old_count] -= 1
                    if freq_of_count[old_count] == 0:
                        del freq_of_count[old_count]
                    freq_of_count[freq[u]] += 1
                    if freq_of_count[freq[u]] == 1:
                        if freq[u] > max_freq:
                            max_freq = freq[u]
                    left += 1
                    window_len = right - left + 1
                    if left > right:
                        break
                if left <= right:
                    if max_freq > window_len / 2:
                        answer = min(answer, window_len)
        if answer == float('inf'):
            out_lines.append("-1")
        else:
            out_lines.append(str(answer))
    sys.stdout.write("\n".join(out_lines))

if __name__ == "__main__":
    solve()
