# Read input
data = sys.stdin.read().strip().split()
if not data:
    exit()

idx = 0
n = int(data[idx]); idx += 1
m = int(data[idx]); idx += 1
k = int(data[idx]); idx += 1

# Build adjacency list
adj = [[] for _ in range(n + 1)]
for _ in range(m):
    v = int(data[idx]); idx += 1
    u = int(data[idx]); idx += 1
    adj[v].append(u)
    adj[u].append(v)

# Try to find a long path using DFS
def dfs_path(start):
    visited = [False] * (n + 1)
    path = []

    def dfs(v, prev, depth):
        if depth > len(path):
            path.append(v)

        for neighbor in adj[v]:
            if neighbor != prev and depth + 1 <= len(path):
                if not visited[neighbor]:
                    visited[neighbor] = True
                    dfs(neighbor, v, depth + 1)
                    visited[neighbor] = False
                    # If we found a longer path, we can return early
                    if depth + 1 > len(path) - 1:
                        path.pop()
        if depth == len(path) - 1:
            path.pop()
        return

    # Try multiple starting points
    for i in range(1, n + 1):
        visited[i] = True
        dfs(i, -1, 1)
        visited[i] = False

        if len(path) >= n // k:
            return path
    return None

path = dfs_path(1)

if path:
    print("PATH")
    print(len(path))
    print(' '.join(map(str, path)))
else:
    # Try to find k cycles of length 4
    # First, find all triangles (cycles of length 3) since they're shorter than 4
    # Then use DFS to find cycles of length 4

    def find_cycle(v, prev, depth, cycle):
        if depth > 3:
            if depth == 4:
                return True
            return False

        for neighbor in adj[v]:
            if neighbor != prev:
                if depth > 0:
                    if neighbor in cycle:
                        continue
                cycle.append(neighbor)
                if find_cycle(neighbor, v, depth + 1, cycle):
                    return True
                cycle.pop()
        return False

    used = [False] * (n + 1)
    cycles = []

    for i in range(1, n + 1):
        if not used[i]:
            used[i] = True
            cycle = [i]
            if find_cycle(i, -1, 1, cycle):
                cycles.append(cycle)
                if len(cycles) == k:
                    break

    if len(cycles) >= k:
        print("CYCLES")
        for i in range(k):
            print(len(cycles[i]))
            print(' '.join(map(str, cycles[i])))
    else:
        print(-1)
