n = int(input())
clowns = input().strip()
acrobats = input().strip()

# Count total clowns
clowns_count = sum(1 for ch in clowns if ch == '1')

# We need exactly n/2 clowns in total
if clowns_count != n // 2:
    print(-1)
else:
    # Try all possible combinations of n/2 artists
    from itertools import combinations

    # Find a valid combination
    for indices in combinations(range(n), n // 2):
        # Count clowns in first group
        clowns_first = 0
        for i in indices:
            if clowns[i] == '1':
                clowns_first += 1

        # Count acrobats in second group
        acrobats_second = 0
        for i in range(n):
            if i not in indices:
                if acrobats[i] == '1':
                    acrobats_second += 1

        if clowns_first == acrobats_second:
            # Format and print the answer
            print(' '.join(str(i + 1) for i in indices))
            break
"}

