MOD = 10**9 + 7

# dp[u][d]: number of ways to color subtree rooted at u such that distance from u to closest black vertex is exactly d
# We need to ensure that for all vertices v, the distance from v to a black vertex is ≤ k

# Actually, we need to use a DP where we track the distance from the root to the closest black vertex
# Let's use a simpler approach: dp[u] = number of ways to color the subtree rooted at u such that the condition holds

def solve():
    # We'll use a DP where we track the distance from u to the closest black vertex in its subtree

    def dfs(u, parent, d):  # d = distance from u to closest black in subtree rooted at u
        # Return (ways, min_distance)

        # Base case: leaf node
        if len(edges[u]) == 1 and u != parent:
            # This is a leaf (u is not the root)
            if d == 0:
                # closest black is u itself
                return (1, 0)  # 1 way (u is black)
            elif d == 1:
                # closest black is child, but we're at leaf
                # u itself must be black, but this would change distance
                # Actually, if u is not black, then closest black is at distance 1 from child
                # So u can be black or not
                if parent == -1:
                    # u is root, can be black or not
                    ways = 2
                    min_dist = 0  # if black, distance 0; if not, distance 1 from child
                    return (ways, min_dist)
                else:
                    # u is child, so u can be black or not
                    if u is black: return (1, 0)
                    if u is not black: return (1, 1)
                    return (1, 1)
            else:
                # d > 1, u cannot be covered
                return (0, 2)

        # Recursive case
        ways = 0

        # Try painting u black
        if d == 0:
            ways_paint_black = 1
            for v in edges[u]:
                if v != parent:
                    w, _ = dfs(v, u, 0)  # distance from v to closest black is at most 0 (since u is black)
                    ways_paint_black = (ways_paint_black * w) % MOD
            ways = ways_paint_black

        # Try not painting u black
        if d > 1:
            # We need at least one child to be painted black within distance ≤ k
            ways_not_paint_black = 0
            for v in edges[u]:
                if v != parent:
                    w, min_dist = dfs(v, u, d - 1)  # distance from v to closest black is at most d-1
                    ways_not_paint_black = (ways_not_paint_black + w) % MOD
            ways = (ways + ways_not_paint_black) % MOD

        # Determine min_distance from u to closest black
        # If we painted u black, min_dist = 0
        # If we didn't paint u black, min_dist = min of min_dist from children

        return (ways, min_dist)

    result = dfs(1, -1, k)  # distance from root to closest black in subtree is at most k
    return result[0]

