import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    n = int(data[0])
    X = set(map(int, data[1:1+n]))

    # Find the maximum block number (s)
    s = max(X) if X else 1000000  # if X empty, s = 1000000

    sum_x = sum(x - 1 for x in X)

    # If X is empty, we need {s}
    if not X:
        print(1)
        print(s)
        return

    # Find remaining blocks
    R = []
    for y in range(1, s + 1):
        if y not in X:
            R.append(y)

    # Sort remaining blocks in descending order
    R.sort(reverse=True)

    # Greedily add blocks until condition is satisfied
    current_sum = 0
    result = []
    for y in R:
        result.append(y)
        current_sum += (s - y)
        if current_sum >= sum_x:
            break

    # Check if we need to adjust
    if current_sum > sum_x:
        # We went over, need to remove the last block
        result.pop()
    elif current_sum < sum_x:
        # We need to add more blocks
        for y in R:
            if y not in result:
                result.append(y)
                current_sum += (s - y)
                if current_sum >= sum_x:
                    break

    # Output
    print(len(result))
    print(' '.join(map(str, result)))

if __name__ == "__main__":
    solve()
