import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    crossword = data[1]
    m = int(data[2])
    words = []
    idx = 3

    for _ in range(m):
        word = data[idx]
        points = int(data[idx + 1])
        words.append((word, points))
        idx += 2

    x = int(data[idx])

    # Find all occurrences of all words
    occurrences = []
    for i, (word, points) in enumerate(words):
        len_word = len(word)
        for start in range(n - len_word + 1):
            if crossword[start:start+len_word] == word:
                # Record the start index (inclusive) and end index (inclusive)
                occurrences.append((start, start + len_word - 1, i, points))

    # Create a mapping from position to available words
    pos_to_words = [[] for _ in range(n)]
    for start, end, _, points in occurrences:
        for j in range(start, end + 1):
            pos_to_words[j].append((points, start, end))

    # Greedy by position: For each position, match the word with the highest points that covers it
    used = [[0] * n for _ in range(x)]  # x uses per position
    total_score = 0

    for i in range(x):
        for pos in range(n):
            # Find all words that cover this position and haven't been fully used
            available = []
            for points, start, end in pos_to_words[pos]:
                if all(used[i][start + j] == 0 for j in range(end - start + 1)):
                    available.append((points, start, end))

            if available:
                # Match the word with the highest points
                available.sort(key=lambda w: -w[0])
                points, start, end = available[0]

                # Mark these positions as used
                for j in range(start, end + 1):
                    used[i][j] = 1

                total_score += points

    print(total_score)

if __name__ == "__main__":
