# Check if already valid (all H contiguous, all T contiguous)
def is_valid(animals, h_count):
    # Find contiguous H blocks
    blocks = []
    i = 0
    while i < n:
        if animals[i] == 'H':
            j = i + 1
            while j < n and animals[j] == 'H':
                j += 1
            blocks.append((i, j-1))  # block start, end (inclusive)
            i = j
        else:
            i += 1

    # In a circle, if there's 1 H block, there must be 1 T block
    if len(blocks) == 1:
        # Check if all H's in the block are contiguous
        return True
    elif len(blocks) == 2:
        # Check if the two H blocks are separated by exactly one T block
        if h_count == 2:
            # Special case: exactly 2 H's and 1 T
            # They should be H, T, H in some rotation
            return False
        return True
    else:
        return False

# If already valid, output 0
if is_valid(animals, h_count):
    print(0)
else:
    # Need to find minimal swaps
    min_swaps = n

    # Try all possible contiguous blocks of size h_count
    for i in range(n):
        # Block from i to (i + h_count - 1) mod n
        # This is a contiguous block of exactly h_count positions
        block = animals[i:i+h_count] + animals[i+h_count:i+h_count + (n - h_count)]

        # Count mismatches
        mismatches = 0
        for j in range(h_count):
            if block[j] != 'H':
