import sys

def solve() -> None:
    k, b, n, t = map(int, sys.stdin.read().split())

    # Calculate z from first experiment (starting with 1)
    if k == 1:
        # Sum of geometric series
        z = 1 + b * n
    else:
        # k^n * 1 + b * (k^(n-1) + ... + k^0) = k^n + b * (k^n - 1) / (k - 1)
        k_power_n = pow(k, n)
        z = k_power_n + b * (k_power_n - 1) // (k - 1)

    # Calculate seconds needed from t
    if k == 1:
        # Need t + b * m >= z => m >= (z - t) // b
        seconds = max(0, (z - t + b - 1) // b)
    else:
        seconds = 0
        current = t
        while current < z:
            current = k * current + b
            seconds += 1

    sys.stdout.write(str(seconds))

if __name__ == "__main__":
    solve()
"}

