n, k = map(int, input().split())

sum1 = k * (k + 1) // 2
if n < sum1:
    print(-1)
else:
    dmax = n // sum1
    # Find all divisors of n
    divisors = set()
    d = 1
    while d * d <= n:
        if n % d == 0:
            divisors.add(d)
            divisors.add(n // d)
        d += 1
    # Find maximum divisor <= dmax
    ans = -1
    for d in divisors:
        if d <= dmax:
            ans = d
    # Ensure we found
    if ans == -1:
        print(-1)
    else:
        sequence = [ans * i for i in range(1, k+1)]
        print(' '.join(map(str, sequence)))
"}

