        for j in range(1, int((i + 1) ** 0.5) + 1):
            if (i + 1) % j == 0:
                # j is a divisor
                dp[i] = max(dp[i], dp[j - 1] + 1)
                # i + 1 / j is also a divisor, but it's >= j
