import sys

class SegmentTree:
    def __init__(self, n, data):
        self.n = n
        self.N = 1
        while self.N < self.n:
            self.N <<= 1
        self.tree = [0] * (2 * self.N)
        self.lazy = [None] * (2 * self.N)
        for i in range(n):
            self.tree[self.N + i] = data[i]
        for i in range(self.N - 1, 0, -1):
            self.tree[i] = max(self.tree[2*i], self.tree[2*i+1])

    def _push(self, node, l, r):
        if self.lazy[node] is not None:
            val = self.lazy[node]
            self.tree[node] = val
            if l != r:  # Not a leaf
                self.lazy[2*node] = val
                self.lazy[2*node+1] = val
            self.lazy[node] = None

    def _update_range(self, a, b, val, node, l, r):
        self._push(node, l, r)
        if a > r or b < l:
            return
        if a <= l and r <= b:
            self.lazy[node] = val
            self._push(node, l, r)
            return
        mid = (l + r) // 2
        self._update_range(a, b, val, 2*node, l, mid)
        self._update_range(a, b, val, 2*node+1, mid+1, r)
        self.tree[node] = max(self.tree[2*node], self.tree[2*node+1])

    def update(self, a, b, val):
        self._update_range(a, b, val, 1, 1, self.N)

    def _query_range(self, a, b, node, l, r):
        self._push(node, l, r)
        if a > r or b < l:
            return -float('inf')
        if a <= l and r <= b:
            return self.tree[node]
        mid = (l + r) // 2
        left = self._query_range(a, b, 2*node, l, mid)
        right = self._query_range(a, b, 2*node+1, mid+1, r)
        return max(left, right)

    def query(self, a, b):
        return self._query_range(a, b, 1, 1, self.N)

def solve():
    data = sys.stdin.read().split()
    it = iter(data)
    n = int(next(it))
    a = [int(next(it)) for _ in range(n)]
    m = int(next(it))
    boxes = []
