        w = int(next(it))
        h = int(next(it))
        boxes.append((w, h))

    st = SegmentTree(n, a)

    out = []
    for w, h in boxes:
        bottom = st.query(1, w)
        out.append(str(bottom))
        top = bottom + h
        st.update(1, w, top)

    sys.stdout.write("\n".join(out))

if __name__ == "__main__":
    solve()
