import sys

def days_in_month(mon, y):
    if mon == 2:
        return 28 + (1 if is_leap(y) else 0)
    elif mon in [1, 3, 5, 7, 8, 10, 12]:
        return 31
    else:
        return 30

def is_leap(y):
    return y % 4 == 0 and (y % 100 != 0 or y % 400 == 0)

def days_from_start(y, m, d):
    # days from 1900-01-01 to y, m, d inclusive
    total = 0
    for month in range(1, m):
        total += days_in_month(month, y)
    total += d
    return total

def days_between(y1, m1, d1, y2, m2, d2):
    if y1 > y2:
        y1, y2, m1, m2, d1, d2 = y2, y1, m2, m1, d2, d1
    # same year
    if y1 == y2:
        d1_total = days_from_start(y1, m1, d1)
        d2_total = days_from_start(y1, m2, d2)
        return d2_total - d1_total + 1
    # cross year
    total = (365 + is_leap(y1)) - days_from_start(y1, m1, d1) + 1
    for y in range(y1 + 1, y2):
        total += 365 + is_leap(y)
    d2_total = days_from_start(y2, m2, d2)
    total += d2_total
    return total

# Read input
lines = [line.strip() for line in sys.stdin if line.strip()]
if len(lines) < 2:
    exit()

y1, m1, d1 = map(int, lines[0].split(':'))
y2, m2, d2 = map(int, lines[1].split(':'))

# Compute days
ans = days_between(y1, m1, d1, y2, m2, d2)
print(ans)
"}

