# Build adjacency list
adj = [[] for _ in range(n + 1)]
edges = []

for _ in range(m):
    u, v = map(int, input().split())
    adj[u].append((v, len(edges)))
    adj[v].append((u, len(edges)))
    edges.append((u, v))

# Tarjan's algorithm for finding bridges
# Time complexity: O(V + E)
time = [0] * (n + 1)
visited = [False] * (n + 1)
bridges = []

def dfs(u, parent):
    visited[u] = True
    time[u] = 1

    for v, idx in adj[u]:
        if v == parent:
            continue

        if not visited[v]:
            dfs(v, u)
            # Check if edge (u, v) is a bridge
            if time[v] > time[u]:
                # If the edge from u to v is a bridge
                bridges.append(idx)
        else:
            # Back edge, not a bridge
            pass

        # Update discovery time for u (we could use min, but we just need to know if there's any back edge)
        if time[v] < time[u]:
            time[u] = time[v]

dfs(1, -1)

if len(bridges) > 0:
    print(0)
else:
    print(1)

# If no bridges, orient the edges with DFS
