def solve() -> None:
    MOD = 998244353

    n, m = map(int, input().split())
    a = list(map(int, input().split()))

    # DP[i][x] = number of ways to get XOR x using first i dolls
    # We'll use a dictionary to store the counts for each XOR value
    dp = {0: 1}

    for val in a:
        new_dp = dict()

        for xor_val, count in dp.items():
            # Don't pick this doll
            if xor_val in new_dp:
                new_dp[xor_val] = (new_dp[xor_val] + count) % MOD
            else:
                new_dp[xor_val] = count % MOD

            # Pick this doll
            new_xor = xor_val ^ val
            if new_xor in new_dp:
                new_dp[new_xor] = (new_dp[new_xor] + count) % MOD
            else:
                new_dp[new_xor] = count % MOD

        dp = new_dp

    # Now count how many subsets produce each XOR value with specific bit counts
    answer = [0] * (m + 1)

    for count, subset_count in dp.items():
        # Count the number of 1-bits in the binary representation of count
        bit_count = bin(count).count('1')
        if bit_count <= m:
            answer[bit_count] = (answer[bit_count] + subset_count) % MOD

    print(' '.join(map(str, answer)))

