                        elif j < (n - 1) // 2 + 1:
                            result.append(-1)  # Team j wins
                        else:
                            # This is the last set of games, we need to complete the wins
                            # Actually, for odd n, we can just have the last game be a win
                            # for the last team
                            if i == n - 1:
                                result.append(-1)  # Team i is the last team
                            else:
                                result.append(1)  # Team i wins

                # This is not the best construction, let me simplify
                # For odd n, we can just have a cycle: 1 beats 2, 2 beats 3, ..., n-1 beats 1
