                        if i == j - 1:
                            result.append(1)
                        elif j == n - 1 and i == 0:
                            result.append(-1)
                        else:
                            result.append(-1)  # This is not correct

                # Let me use the cycle pattern for odd n
                result = []
                for i in range(n-1):
                    for j in range(i + 1, n):
                        if i < j - 1:
                            result.append(1)  # i wins
                        else:
                            result.append(-1)  # j wins

                # Check if each team has exactly (n-1)//2 wins
                # This should work for odd n
        else:  # n is even
            T = 1
            W = total_games - 1
            # Check if this gives an integer score
            if (2 * T + 3 * W) % n == 0:
                # At least 1 tie
                # Tie between team 1 and team 2
                result = [0] + [-1] * (total_games - 1)
