        min_len = float('inf')

        # Try each possible subarray [i, j]
        for i in range(n):
            for j in range(i, n):
                # Get subarray
                sub = a[i:j+1]

                # Count frequencies
                freq = {}
                for num in sub:
                    freq[num] = freq.get(num, 0) + 1

                # Find maximum frequency
                max_freq = max(freq.values())

                # Check domination condition
                dominated = True
                for v in freq:
                    if freq[v] >= max_freq:
                        dominated = False
                        break

                # A subarray of length >= 2 is dominated if the maximum frequency is strictly greater
                # than all other frequencies. That means max_freq must be > 1, and max_freq > all others.
                # But if max_freq == 1, then no single element dominates.
                if dominated and max_freq > 1:
                    min_len = min(min_len, j - i + 1)

