    data = sys.stdin.read().split()
    if not data:
        return
    it = iter(data)
    q = int(next(it))
    out_lines = []
    for _ in range(q):
        n = int(next(it))
        s = [int(next(it)) for _ in range(n)]
        # Count powers of two
        power_counts = {}  # power -> count
        max_power = 2048  # 2^11
        for x in s:
            if x <= max_power:
                power = 1
                while power <= x:
                    power *= 2
                power //= 2
                power_counts[power] = power_counts.get(power, 0) + 1
        # Process from smallest to largest
        powers = sorted(power_counts.keys())
        for p in powers:
            count = power_counts[p]
            if count % 2 == 0:
                pairs = count // 2
                power_counts[p] = 0
                power_counts[p * 2] = power_counts.get(p * 2, 0) + pairs
            else:
                pairs = count // 2
                power_counts[p] = 1  # one unpaired
                power_counts[p * 2] = power_counts.get(p * 2, 0) + pairs
        # Check if 2048 in power_counts with count >= 1
        if power_counts.get(2048, 0) >= 1:
            out_lines.append("YES")
        else:
            out_lines.append("NO")
    sys.stdout.write("\n".join(out_lines))

if __name__ == "__main__":
    solve()
