import sys

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    n = int(next(it))
    k = int(next(it))
    s = next(it)
    print(s)

    # Preprocess: for each character, list all positions in s
    char_positions = {}
    for pos, ch in enumerate(s, start=1):
        if ch not in char_positions:
            char_positions[ch] = []
        char_positions[ch].append(pos)

    # For each potential address
    for _ in range(n):
        c = next(it)

        # If character not in s, add length of potential address
        if len(c) > 1:
            # For each character in potential address, check if it exists in s
            # and find closest position
            total = 0
            for i, ch in enumerate(c, start=1):
                if ch in char_positions:
                    # Binary search for closest position
                    positions = char_positions[ch]
                    low, high = 0, len(positions)
                    while low < high:
                        mid = (low + high) // 2
                        if positions[mid] < i:
                            low = mid + 1
                        else:
                            high = mid
                    # low is the first position >= i
                    # closest could be positions[low-1] or positions[low]
                    if low == 0:
                        closest = positions[0]
                    elif low == len(positions):
                        closest = positions[-1]
                    else:
                        closest = positions[low-1] if abs(positions[low-1] - i) < abs(positions[low] - i) else positions[low]
                    total += abs(i - closest)
                else:
                    total += len(c)
            print(total)
        else:
            print(0)

