import sys

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    idx = 0
    n = int(data[idx]); idx += 1
    a = [0] * (n + 1)
    for i in range(1, n + 1):
        a[i] = int(data[idx]); idx += 1

    # Build tree and find parent
    tree = [[] for _ in range(n + 1)]
    parent = [0] * (n + 1)
    for _ in range(n - 1):
        u = int(data[idx]); idx += 1
        v = int(data[idx]); idx += 1
        tree[u].append(v)
        tree[v].append(u)
        parent[v] = u

    # DFS to compute subtree sums
    subtree_sum = [0] * (n + 1)

    def dfs(node, parent):
        subtree_sum[node] = a[node]
        for neighbor in tree[node]:
            if neighbor != parent:
                dfs(neighbor, node)
                subtree_sum[node] += subtree_sum[neighbor]
        return

    dfs(1, -1)

    # Strategy: choose the root and the best child, or choose two of the best children
    max_sum = -float('inf')

    # Find all children of the root
    children_of_root = [i for i in range(1, n + 1) if parent[i] == 1]

    # Case 1: Choose root and the best child
    if children_of_root:
        best_child_sum = max(subtree_sum[i] for i in children_of_root)
        max_sum = subtree_sum[1] + best_child_sum

    # Case 2: Choose two children of the root that are not overlapping
    if len(children_of_root) >= 2:
        top_two_children = sorted([subtree_sum[i] for i in children_of_root], reverse=True)[:2]
        max_sum = max(max_sum, top_two_children[0] + top_two_children[1])

    # Strategy: Find the top two subtrees that are not overlapping
    # We can iterate through all nodes
    for u in range(1, n + 1):
        for v in range(1, n + 1):
            if u != v:
                def is_in_subtree(u, v):
                    while v != 0:
                        if v == u:
                            return True
                        v = parent[v]
                    return False

                if not is_in_subtree(u, v) and not is_in_subtree(v, u):
                    max_sum = max(max_sum, subtree_sum[u] + subtree_sum[v])

