    data = list(map(int, input))
    if not data:
        return

    idx = 0
    n, m, k = data[idx], data[idx+1], data[idx+2]
    idx += 3

    a = []
    b = []
    c = []
    portals = [[] for _ in range(n+1)]  # 1-indexed

    for i in range(1, n+1):
