        a.append(ai)
        b.append(bi)
        c.append(ci)
        idx += 3

    for _ in range(m):
        u, v = data[idx], data[idx+1]
        portals[u].append(v)
        idx += 2

    # dp[i][w] = max importance after capturing castle i, having w warriors available
    # We use a dictionary of dictionaries for space efficiency
    dp = {}  # dp[i][w] = max importance
    dp[0] = {k: 0}

    for i in range(1, n + 1):
        # Need to capture castle i with at least a[i-1] warriors
        # Get all states from dp[i-1]
        states = dp[i-1]

        if not states:
            return -1

        # Try to capture castle i
        new_dp = {}
        for warriors, score in states.items():
            if warriors >= a[i-1]:
                # After capturing castle i, we have:
                # warriors = warriors - a[i-1] + b[i-1]
                # Actually, we spend a[i-1] warriors to capture, then gain b[i-1]
                new_warriors = warriors - a[i-1] + b[i-1]

                # Now we can defend castle i
                if new_warriors >= 1:
                    if new_warriors not in new_dp or score + c[i-1] > new_dp[new_warriors]:
                        new_dp[new_warriors] = max(new_dp.get(new_warriors, -1), score + c[i-1])

                # And we can use portals to defend previous castles
                for j in portals[i]:
                    if new_warriors >= 1:
                        if new_warriors not in new_dp or score + c[j-1] > new_dp[new_warriors]:
                            new_dp[new_warriors] = max(new_dp.get(new_warriors, -1), score + c[j-1])

        # Update dp
        dp[i] = new_dp
        if not dp[i]:
            return -1

    # Return the maximum importance score
    if dp[n]:
        return max(dp[n].values())
    else:
        return -1

if __name__ == "__main__":
    result = solve()
    print(result)
