                # Items: c[i-1] (castle i) and c[j-1] for all j in portals[i]

                # Let's do a 0/1 knapsack
                temp = {warriors_new: score_prev}

                # Include castle i
                if warriors_new >= 1:
                    if warriors_new not in temp or temp[warriors_new] < score_prev + c[i-1]:
                        temp[warriors_new] = score_prev + c[i-1]

                # Include previous castles via portals
                for j in portals[i]:
                    if warriors_new >= 1:
                        if warriors_new not in temp or temp[warriors_new] < score_prev + c[j-1]:
                            temp[warriors_new] = score_prev + c[j-1]

                # Also, we could defend both castle i and a previous castle
                for j in portals[i]:
                    if warriors_new >= 2:
                        if warriors_new not in temp or temp[warriors_new] < score_prev + c[i-1] + c[j-1]:
                            temp[warriors_new] = score_prev + c[i-1] + c[j-1]

                # Now update new_dp with the best scores
                for w in temp:
                    if w not in new_dp or temp[w] > new_dp[w]:
                        new_dp[w] = temp[w]

        dp[i] = new_dp
        if not dp[i]:
            return -1

    return max(dp[n].values()) if dp[n] else -1

if __name__ == "__main__":
    result = solve()
    print(result)

