import sys

def find_matching(n, edges):
    used = [False] * (3 * n + 1)
    matching = []

    for i, (u, v) in enumerate(edges):
        if not used[u] and not used[v]:
            matching.append(i + 1)  # 1-indexed edge index
            used[u] = True
            used[v] = True

            if len(matching) == n:
                return matching

    return None

def find_independent_set(n, edges, adj):
    used = [False] * (3 * n + 1)
    independent_set = []

    for v in range(1, 3 * n + 1):
        if not used[v]:
            is_valid = True
            for neighbor in adj[v]:
                if used[neighbor]:
                    is_valid = False
                    break

            if is_valid:
                independent_set.append(v)
                used[v] = True

                if len(independent_set) == n:
                    return independent_set

    return None

def solve():
    data = sys.stdin.read().split()
    if not data:
        return

    it = iter(data)
    T = int(next(it))

    for _ in range(T):
        n = int(next(it))
        m = int(next(it))

        edges = []
        adj = [[] for _ in range(3 * n + 1)]

