x, y, x0, y0 = map(int, input().split())
s = input().strip()

# First, simulate the robot's path and record when each position is first visited
first_visit = {}
x_current, y_current = x0, y0
first_visit[(x_current, y_current)] = 0  # start position at step 0

for i, move in enumerate(s):
    if move == 'U':
        if x_current > 1:
            x_current -= 1
    elif move == 'D':
        if x_current < x:
            x_current += 1
    elif move == 'L':
        if y_current > 1:
            y_current -= 1
    elif move == 'R':
        if y_current < y:
            y_current += 1

    position = (x_current, y_current)
    if position not in first_visit:
        first_visit[position] = i + 1  # 1-indexed step

# Now count how many tests result in explosion at each step
result = [0] * (len(s) + 1)

# Positions that are visited in the path
for pos, step in first_visit.items():
    result[step] += 1

# Positions that are not visited in the path will explode at the final step
final_step = len(s)
result[final_step] += (x * y - len(first_visit))

# Output
print(' '.join(map(str, result)))
