clowns = []
for i in range(n):
    if c_str[i] == '1':
        clowns.append(i + 1)  # 1-indexed

# Check if we can split
if n % 4 != 0:
    print(-1)
else:
    # We need exactly n/4 clowns in the first performance
    needed_clowns = n // 4
    if len(clowns) < needed_clowns:
        print(-1)
    else:
        # Choose needed clowns and (n/2 - needed_clowns) non-clowns
        first_performance = clowns[:needed_clowns]
        non_clowns = []
        for i in range(1, n + 1):
            if i not in first_performance and c_str[i - 1] == '0':
                non_clowns.append(i)
        first_performance.extend(non_clowns[: (n // 2) - needed_clowns])

        print(' '.join(map(str, first_performance)))
