    word_positions = {}
    for word, points in words:
        word_positions[word] = []
        len_word = len(word)
        for i in range(n - len_word + 1):
            if s[i:i+len_word] == word:
                word_positions[word].append(i)

    # dp[i][j] = max points using first i positions with j uses
    dp = [[-1] * (x + 1) for _ in range(n + 1)]
    dp[0][0] = 0

    for i in range(n + 1):
        for j in range(x + 1):
            if dp[i][j] == -1:
                continue

            # Try not using any word ending at position i
            if i > 0:
                dp[i][j] = max(dp[i][j], dp[i-1][j])

