{"code": "t = int(input())
for _ in range(t):
    n, m = map(int, input().split())
    a = list(map(int, input().split()))

    # Count occurrences of each remainder
    count = [0] * m
    for num in a:
        r = num % m
        count[r] += 1

    # We need to find the minimum number of arrays
    # For remainder 0, we can just create one array with all 0-remainder elements
    # For remainder r where r != m - r, we can pair them
    # For remainder r where r == m - r (i.e., r = m/2), we need one array per group

    ans = 1
    # Process remainder 0
    if count[0] > 0:
        ans = max(ans, count[0])

    # Process other remainders
    for r in range(1, m // 2 + 1):
        if r == m - r:
            # r = m/2, need one array per group
            ans = max(ans, count[r])
        else:
            # Pair remainder r with m-r
            if count[r] > 0:
                ans = max(ans, count[r])
            if count[m - r] > 0:
                ans = max(ans, count[m - r])

    print(ans)
