def count_min_swaps(animal_positions):
    n = len(animal_positions)
    if n == 0:
        return 0

    count_h = animal_positions.count('H')

    # For a circle, if we have a contiguous block of H's, all H's
    # in that block don't need to be swapped

    # Find the maximum contiguous block of H's (circular array)
    max_consecutive = 1
    current = 1

    if animal_positions[0] == 'H':
        current = 1
    else:
        current = 0

    for i in range(1, n):
        if animal_positions[i] == 'H':
            current += 1
        else:
            current = 0

        max_consecutive = max(max_consecutive, current)

    # If we already have all H's contiguous
    if max_consecutive >= count_h:
        return 0

    # Otherwise, we need at least (count_h - max_consecutive) swaps
    return count_h - max_consecutive

