    # If we can get infinite gold from nothing (spell 2: c=0, d>0)
    if c == 0 and d > 0:
        print("Ron")
        return

    # If we can get infinite lead from nothing (spell 1: a=0, b>0)
    if a == 0 and b > 0:
        # And we can convert lead to gold (c > 0)
        if c > 0:
            print("Ron")
            return

    # If we can get infinite sand from nothing (spell 3: e=0, f>0)
    if e == 0 and f > 0:
        # And we can convert sand to lead (a > 0) and lead to gold (c > 0)
        if a > 0 and c > 0:
            print("Ron")
            return

    # General case: check if we can create infinite gold via cycle
    # Cycle: sand -> lead -> gold -> sand
    # f * d * b (final sand) > a * c * e (initial sand)
    if f * d * b > a * c * e:
        print("Ron")
    else:
        print("Hermione")

solve()
