        h = int(next(it))
        boxes.append((w, h))

    # Segment tree for range max query and range set update.
    class SegmentTree:
        def __init__(self, size, initial):
            self.n = size
            self.size = 1
            while self.size < size:
                self.size <<= 1
            self.data = [0] * (2 * self.size)
            self.lazy = [None] * (2 * self.size)
            for i in range(size):
                self.data[self.size + i] = initial[i]
            for i in range(self.size - 1, 0, -1):
                self.data[i] = max(self.data[2*i], self.data[2*i+1])
        def push(self, node, l, r):
            if self.lazy[node] is not None and node < self.size:
                val = self.lazy[node]
                self.lazy[2*node] = val
                self.lazy[2*node+1] = val
                self.data[2*node] = val
                self.data[2*node+1] = val
                self.lazy[node] = None
        def update_range(self, a, b, val, node=1, l=0, r=None):
            if r is None:
                r = self.size - 1
            if a > r or b < l:
                return
            if a <= l and r <= b:
                self.data[node] = val
                self.lazy[node] = val
                return
            self.push(node, l, r)
            mid = (l + r) // 2
            self.update_range(a, b, val, 2*node, l, mid)
            self.update_range(a, b, val, 2*node+1, mid+1, r)
            self.data[node] = max(self.data[2*node], self.data[2*node+1])
        def query_max(self, a, b, node=1, l=0, r=None):
            if r is None:
                r = self.size - 1
            if a > r or b < l:
                return -1
            if a <= l and r <= b:
                return self.data[node]
            self.push(node, l, r)
            mid = (l + r) // 2
            left = self.query_max(a, b, 2*node, l, mid)
            right = self.query_max(a, b, 2*node+1, mid+1, r)
            return max(left, right)

