def solve():
    import sys
    input = sys.stdin.read()
    data = input.split()

    t = int(data[0])
    idx = 1

    max_n = 0
    queries = []

    for _ in range(t):
        n = int(data[idx])
        idx += 1
        sizes = list(map(int, data[idx:idx+n]))
        idx += n

        max_n = max(max_n, n)
        queries.append((n, sizes))

    # Precompute divisors for each number up to max_n
    divisors = [[] for _ in range(max_n + 1)]
    for i in range(1, max_n + 1):
        for j in range(i, max_n + 1, i):
            divisors[j].append(i)  # divisors of j include i

    results = []
    for n, sizes in queries:
        dp = [1] * n  # dp[i] = max length ending at index (i+1) 1-indexed

        for i in range(n):
            for j in divisors[i+1]:  # j is a divisor of (i+1)
                if j <= i:  # j must be <= i (1-indexed)
                    if sizes[j-1] < sizes[i]:
                        dp[i] = max(dp[i], dp[j-1] + 1)

        results.append(max(dp))

    for res in results:
        print(res)

solve()
