def is_leap_year(year):
    if year % 4 != 0:
        return False
    if year % 100 != 0:
        return True
    if year % 400 != 0:
        return False
    return True

def days_in_month(year, month):
    if month == 2:
        return 29 if is_leap_year(year) else 28
    elif month in [4, 6, 9, 11]:
        return 30
    else:
        return 31

def date_to_days(year, month, day):
    days = 0
    for y in range(1900, year):
        days += 366 if is_leap_year(y) else 365
    for m in range(1, month):
        days += days_in_month(year, m)
    return days + day - 1

# Read input
line1 = input().strip()
line2 = input().strip()

# Parse dates
year1, month1, day1 = map(int, line1.split(':'))
year2, month2, day2 = map(int, line2.split(':'))

# Calculate days between
if year1 < year2:
    days = date_to_days(year2, month2, day2) - date_to_days(year1, month1, day1)
else:
    # If year1 > year2, we need to be careful with the difference
    # We can just take absolute value
    days = abs(date_to_days(year2, month2, day2) - date_to_days(year1, month1, day1))

print(days)
